import { useEffect, useMemo, useRef, useState } from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { ArrowLeftIcon } from "lucide-react"

import { useCollection } from "@/lib/mini/store"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"

import { ListPeek } from "./list-peek"

type BookStatus = "To read" | "Reading" | "Done"

type Book = {
  id: string
  title: string
  author: string
  status: BookStatus
  added: string
  notes: string
}

type Preview = "live" | "empty" | "loading" | "error"

const STATUSES: BookStatus[] = ["To read", "Reading", "Done"]
const PREVIEWS: Preview[] = ["live", "empty", "loading", "error"]

const SEED: Book[] = [
  { id: "BK-01", title: "The Lighthouse Keeper's Almanac", author: "M. Okafor", status: "To read", added: "2026-09-02", notes: "Recommended for the tide tables alone. Skim the appendix on fog signals first." },
  { id: "BK-02", title: "Small Gardens, Large Patience", author: "R. Lindqvist", status: "To read", added: "2026-09-05", notes: "Container planting for a north-facing balcony." },
  { id: "BK-03", title: "A Field Guide to Quiet Machines", author: "T. Nakamura", status: "To read", added: "2026-09-11", notes: "Short chapters on clocks, looms and pumps. Good for the train." },
  { id: "BK-04", title: "The Interesting Narrative of an Exhaustively Documented Voyage Across Three Oceans, Two Mutinies, and One Surprisingly Well-Preserved Wheel of Cheese", author: "Capt. E. Thorne-Whitcombe", status: "To read", added: "2026-09-14", notes: "Deliberately long title to check truncation in the row and wrapping in the panel. Reviews say the cheese chapters are the best part.\n\nThe edition on the shelf is the annotated two-volume set, so budget a few weekends." },
  { id: "BK-05", title: "Ledger of Small Mercies", author: "A. Duarte", status: "To read", added: "2026-09-18", notes: "Short stories. Start with the title story." },
  { id: "BK-06", title: "Maps Nobody Asked For", author: "J. Petrov", status: "To read", added: "2026-09-21", notes: "Essays on amateur cartography." },
  { id: "BK-07", title: "The Slow Compiler", author: "H. Abara", status: "Reading", added: "2026-08-19", notes: "Chapter 6 onward is the interesting part. Halfway through, taking notes on parsing." },
  { id: "BK-08", title: "Salt, Smoke and Time", author: "L. Moreau", status: "Done", added: "2026-06-03", notes: "Preservation techniques by region. The curing tables are worth photocopying." },
  { id: "BK-09", title: "Night Trains of the Interior", author: "S. Varga", status: "Done", added: "2026-06-17", notes: "Travel writing. Loved the dining car chapter." },
  { id: "BK-10", title: "On Keeping Bees Badly", author: "C. Ferreira", status: "Done", added: "2026-07-01", notes: "Funny, practical, and honest about the mistakes." },
  { id: "BK-11", title: "Arithmetic for the Curious", author: "P. Whitlock", status: "Done", added: "2026-07-09", notes: "Good puzzles. Skipped the final proofs." },
  { id: "BK-12", title: "The Cartographer's Apprentice", author: "N. Eze", status: "Done", added: "2026-07-22", notes: "A novel. Reread the ending twice." },
  { id: "BK-13", title: "Rivers of the Low Country", author: "D. Castellano", status: "Done", added: "2026-08-02", notes: "Dense but rewarding. Footnotes are the best bit." },
  { id: "BK-14", title: "Plain Text Forever", author: "K. Sorensen", status: "Done", added: "2026-08-11", notes: "A short polemic on keeping notes in files you can still open in thirty years." },
]

const dateFormat = new Intl.DateTimeFormat("en", { dateStyle: "medium", timeZone: "UTC" })

const formatDate = (iso: string) => dateFormat.format(new Date(`${iso}T00:00:00Z`))

const nextStatus = (status: BookStatus) => STATUSES[(STATUSES.indexOf(status) + 1) % STATUSES.length]

const HINTS = [
  "Click or Space toggle peek",
  "Hold Space peek while pressed",
  "Enter or double-click open full view",
  "j/k move",
  "/ filter",
  "Home/End first or last",
  "Esc clear filter, close peek, then clear highlight",
]

function BookDetail({
  book,
  full = false,
  onMove,
  onRemove,
}: {
  book: Book
  full?: boolean
  onMove: () => void
  onRemove: () => void
}) {
  const Heading = full ? "h1" : "h2"
  return (
    <article className="flex flex-col gap-3">
      <Heading data-mini="title" className={full ? "text-xl font-semibold" : "line-clamp-3 text-base font-semibold"}>
        {book.title}
      </Heading>
      <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
        <Badge variant="secondary">{book.status}</Badge>
        <span>{book.author}</span>
        <span aria-hidden>·</span>
        <span>Added {formatDate(book.added)}</span>
        <span aria-hidden>·</span>
        <span>{book.id}</span>
      </div>
      <p className="text-sm leading-relaxed whitespace-pre-line">{book.notes}</p>
      <div className="flex gap-2">
        <Button size="sm" variant="outline" onClick={onMove}>
          Move to {nextStatus(book.status)}
        </Button>
        <Button size="sm" variant="outline" onClick={onRemove}>
          Remove
        </Button>
      </div>
    </article>
  )
}

export default function Demo() {
  const books = useCollection<Book>("list-peek-demo", SEED)
  const [preview, setPreview] = useState<Preview>("live")
  const [openedId, setOpenedId] = useState<string | null>(null)
  const [highlightedId, setHighlightedId] = useState<string | null>(null)
  const [peekOpen, setPeekOpen] = useState(false)
  const fullViewRef = useRef<HTMLElement>(null)

  const ordered = useMemo(
    () => [...books.items].sort((a, b) => STATUSES.indexOf(a.status) - STATUSES.indexOf(b.status)),
    [books.items]
  )

  const restoreSamples = () => {
    setPreview("live")
    void books.replaceAll(SEED)
  }

  const opened = preview === "live" ? ordered.find((book) => book.id === openedId) : undefined

  const backToList = () => setOpenedId(null)
  const fullViewOpen = opened !== undefined
  useHotkeys("esc", backToList, { enabled: fullViewOpen })
  useEffect(() => {
    if (fullViewOpen) fullViewRef.current?.focus()
  }, [fullViewOpen])

  const removeFromFullView = (book: Book) => {
    const at = ordered.findIndex((item) => item.id === book.id)
    setHighlightedId((ordered[at + 1] ?? ordered[at - 1])?.id ?? null)
    setPeekOpen(false)
    setOpenedId(null)
    void books.remove(book.id)
  }

  const status = preview === "live" ? books.status : preview === "empty" ? "ready" : preview
  const items = preview === "empty" ? [] : ordered

  return (
    <div className="flex h-full min-h-0 flex-col gap-3 p-4">
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-xs text-muted-foreground">State preview (demo only)</span>
        <div role="group" aria-label="State preview" className="flex gap-1">
          {PREVIEWS.map((name) => (
            <Button
              key={name}
              size="xs"
              variant={preview === name ? "default" : "outline"}
              aria-pressed={preview === name}
              onClick={() => setPreview(name)}
              className="capitalize"
            >
              {name}
            </Button>
          ))}
        </div>
      </div>

      <div className="min-h-[24rem] flex-1 overflow-hidden rounded-lg border">
        {opened ? (
          <section
            ref={fullViewRef}
            tabIndex={-1}
            aria-label={`Full view: ${opened.title}`}
            className="flex h-full flex-col outline-none"
          >
            <div className="flex h-11 shrink-0 items-center gap-3 border-b px-3">
              <Button size="sm" variant="ghost" onClick={backToList}>
                <ArrowLeftIcon aria-hidden />
                Back to list
              </Button>
              <span className="text-xs text-muted-foreground">or press Esc</span>
            </div>
            <div className="min-h-0 flex-1 overflow-y-auto p-6">
              <div className="max-w-2xl">
                <BookDetail
                  full
                  book={opened}
                  onMove={() => void books.update(opened.id, { status: nextStatus(opened.status) })}
                  onRemove={() => removeFromFullView(opened)}
                />
              </div>
            </div>
          </section>
        ) : (
          <ListPeek
            autoFocus={highlightedId !== null}
            aria-label="Reading list"
            items={items}
            status={status}
            error={new Error("Could not read the reading list (simulated).")}
            onRetry={() => setPreview("live")}
            groupBy={(book) => book.status}
            filterText={(book) => `${book.id} ${book.title} ${book.author}`}
            renderLead={(book) => book.id}
            renderMeta={(book) => book.author}
            highlightedId={highlightedId}
            onHighlightedIdChange={setHighlightedId}
            peekOpen={peekOpen}
            onPeekOpenChange={setPeekOpen}
            onOpen={(book) => setOpenedId(book.id)}
            emptyTitle="Your reading list is empty"
            emptyAction={{ label: "Restore sample books", onClick: restoreSamples }}
            renderPeek={(book) => (
              <BookDetail
                book={book}
                onMove={() => void books.update(book.id, { status: nextStatus(book.status) })}
                onRemove={() => void books.remove(book.id)}
              />
            )}
          />
        )}
      </div>

      <p className="text-xs text-muted-foreground">{HINTS.join(" · ")}</p>
    </div>
  )
}

import {
  useEffect,
  useEffectEvent,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type MouseEvent as ReactMouseEvent,
  type ReactNode,
} from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { ChevronDownIcon, ChevronUpIcon, XIcon } from "lucide-react"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { ScrollArea } from "@/components/ui/scroll-area"
import { cn } from "@/lib/utils"

export type ListPeekItem = { id: string; title: string }

export type ListPeekProps<T extends ListPeekItem> = {
  items: T[]
  status?: "loading" | "ready" | "error"
  error?: Error
  onRetry?: () => void
  renderPeek: (item: T) => ReactNode
  renderLead?: (item: T) => ReactNode
  renderMeta?: (item: T) => ReactNode
  groupBy?: (item: T) => string
  filterText?: (item: T) => string
  onOpen?: (item: T) => void
  highlightedId?: string | null
  onHighlightedIdChange?: (id: string | null) => void
  peekOpen?: boolean
  onPeekOpenChange?: (open: boolean) => void
  holdThresholdMs?: number
  autoFocus?: boolean
  emptyTitle?: string
  emptyAction?: { label: string; onClick: () => void }
  "aria-label"?: string
}

type Section<T> = { name: string | null; rows: T[] }

const heldFor = (since: number) => performance.now() - since

/** State that follows `value` when the parent passes one and is held locally otherwise. */
function useControllable<T>(
  value: T | undefined,
  initial: T,
  onChange?: (next: T) => void
): [T, (next: T) => void] {
  const [inner, setInner] = useState(initial)
  const controlled = value !== undefined
  const set = (next: T) => {
    if (!controlled) setInner(next)
    onChange?.(next)
  }
  return [controlled ? value : inner, set]
}

function toSections<T extends ListPeekItem>(rows: T[], groupBy?: (item: T) => string): Section<T>[] {
  if (!groupBy) return [{ name: null, rows }]
  const byName = new Map<string, T[]>()
  for (const row of rows) {
    const name = groupBy(row)
    byName.set(name, [...(byName.get(name) ?? []), row])
  }
  return [...byName].map(([name, grouped]) => ({ name, rows: grouped }))
}

const INTERACTIVE =
  "a,button,input,select,textarea,summary,[role=button],[role=link],[contenteditable=true]"

/**
 * Dense list with a keyboard highlight and a read-only side panel ("peek") that
 * follows it. Clicking a row highlights it and toggles the peek; Enter and
 * double-click call `onOpen`, and the host decides what opening means. Takes data
 * as props and never reads the store. Keys act when focus is on the page body or
 * inside this block, never while typing in an input. `autoFocus` focuses the list
 * on mount, for hosts that remount the block after a full view.
 */
export function ListPeek<T extends ListPeekItem>({
  items,
  status = "ready",
  error,
  onRetry,
  renderPeek,
  renderLead,
  renderMeta,
  groupBy,
  filterText,
  onOpen,
  highlightedId: highlightedProp,
  onHighlightedIdChange,
  peekOpen: peekOpenProp,
  onPeekOpenChange,
  holdThresholdMs = 250,
  autoFocus = false,
  emptyTitle = "Nothing here yet",
  emptyAction,
  "aria-label": ariaLabel = "Items",
}: ListPeekProps<T>) {
  const uid = useId()
  const rootRef = useRef<HTMLDivElement>(null)
  const listRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const panelRef = useRef<HTMLElement>(null)
  const hoveredId = useRef<string | null>(null)
  const pressStart = useRef<number | null>(null)
  const previousOrder = useRef<string[]>([])

  const [filter, setFilter] = useState("")
  const [highlightedId, setHighlightedId] = useControllable<string | null>(
    highlightedProp,
    null,
    onHighlightedIdChange
  )
  const [peekOpen, setPeekOpen] = useControllable(peekOpenProp, false, onPeekOpenChange)

  const ready = status === "ready"
  const sections = useMemo(() => {
    const query = filter.trim().toLowerCase()
    const matching = query
      ? items.filter((item) =>
          (filterText ? filterText(item) : item.title).toLowerCase().includes(query)
        )
      : items
    return toSections(matching, groupBy)
  }, [items, filter, filterText, groupBy])
  const rows = useMemo(() => sections.flatMap((section) => section.rows), [sections])
  const activeIndex = rows.findIndex((row) => row.id === highlightedId)
  const active = activeIndex === -1 ? undefined : rows[activeIndex]
  const showPeek = ready && peekOpen && active !== undefined
  const keysOn = ready && items.length > 0

  const rowDomId = (id: string) => `${uid}-row-${encodeURIComponent(id)}`
  const focusList = () => listRef.current?.focus({ preventScroll: true })

  const closePeek = () => {
    const focusInPanel = panelRef.current?.contains(document.activeElement)
    setPeekOpen(false)
    if (focusInPanel) focusList()
  }

  const clickedControl = (event: ReactMouseEvent<HTMLElement>) => {
    const control = (event.target as Element).closest(INTERACTIVE)
    return control !== null && control !== event.currentTarget && event.currentTarget.contains(control)
  }

  const onRowClick = (event: ReactMouseEvent<HTMLElement>, item: T) => {
    if (clickedControl(event)) return
    focusList()
    // the second click of a double-click must not undo the first click's toggle
    if (event.detail > 1) {
      setHighlightedId(item.id)
    } else if (item.id === highlightedId && peekOpen) {
      closePeek()
    } else {
      setHighlightedId(item.id)
      setPeekOpen(true)
    }
  }

  const onRowDoubleClick = (event: ReactMouseEvent<HTMLElement>, item: T) => {
    if (clickedControl(event)) return
    setHighlightedId(item.id)
    onOpen?.(item)
  }

  const highlightByKey = (id: string) => {
    setHighlightedId(id)
    if (document.activeElement !== listRef.current) focusList()
  }

  const move = (to: "next" | "previous" | "first" | "last") => {
    if (rows.length === 0) return
    let index: number
    if (to === "first") index = 0
    else if (to === "last") index = rows.length - 1
    else if (activeIndex === -1) index = to === "next" ? 0 : rows.length - 1
    else index = Math.min(rows.length - 1, Math.max(0, activeIndex + (to === "next" ? 1 : -1)))
    highlightByKey(rows[index].id)
  }

  const inScope = (event: KeyboardEvent) => {
    const target = event.target
    if (target === document.body || target === document.documentElement) return true
    return target instanceof Node && rootRef.current?.contains(target) === true
  }
  const inPanel = (event: KeyboardEvent) =>
    event.target instanceof Node && panelRef.current?.contains(event.target) === true

  const releaseSpace = () => {
    const startedAt = pressStart.current
    pressStart.current = null
    if (startedAt !== null && heldFor(startedAt) >= holdThresholdMs) closePeek()
  }
  const releaseOnBlur = useEffectEvent(() => releaseSpace())
  useEffect(() => {
    const onBlur = () => releaseOnBlur()
    window.addEventListener("blur", onBlur)
    return () => window.removeEventListener("blur", onBlur)
  }, [])

  const navigate = (event: KeyboardEvent, to: Parameters<typeof move>[0]) => {
    if (!inScope(event) || inPanel(event)) return
    event.preventDefault()
    move(to)
  }
  useHotkeys("j,down", (event) => navigate(event, "next"), { enabled: keysOn })
  useHotkeys("k,up", (event) => navigate(event, "previous"), { enabled: keysOn })
  useHotkeys("home", (event) => navigate(event, "first"), { enabled: keysOn })
  useHotkeys("end", (event) => navigate(event, "last"), { enabled: keysOn })

  useHotkeys(
    "space",
    (event) => {
      if (event.type === "keyup") return releaseSpace()
      if (!inScope(event) || inPanel(event)) return
      const target = active ?? rows.find((row) => row.id === hoveredId.current)
      if (!target) return
      event.preventDefault()
      if (event.repeat) return
      if (peekOpen) {
        pressStart.current = null
        closePeek()
        return
      }
      if (!active) highlightByKey(target.id)
      setPeekOpen(true)
      pressStart.current = performance.now()
    },
    { enabled: keysOn, keydown: true, keyup: true }
  )

  useHotkeys(
    "enter",
    (event) => {
      if (!onOpen || !active || !inScope(event) || inPanel(event)) return
      event.preventDefault()
      onOpen(active)
    },
    { enabled: keysOn }
  )

  useHotkeys(
    "slash",
    (event) => {
      if (!inScope(event)) return
      event.preventDefault()
      inputRef.current?.focus()
    },
    { enabled: ready }
  )

  useHotkeys(
    "esc",
    (event) => {
      if (!inScope(event)) return
      if (inPanel(event)) {
        if (peekOpen) {
          event.preventDefault()
          closePeek()
        }
        return
      }
      if (filter) {
        event.preventDefault()
        setFilter("")
      } else if (peekOpen) {
        event.preventDefault()
        closePeek()
      } else if (highlightedId !== null) {
        event.preventDefault()
        setHighlightedId(null)
      }
    },
    { enabled: ready }
  )

  const reconcile = useEffectEvent(() => {
    if (!ready) return
    if (highlightedId !== null && !rows.some((row) => row.id === highlightedId)) {
      const removed = !items.some((item) => item.id === highlightedId)
      const at = previousOrder.current.indexOf(highlightedId)
      const neighbour = removed && at !== -1 ? rows[Math.min(at, rows.length - 1)] : undefined
      setHighlightedId(neighbour?.id ?? null)
      if (peekOpen) setPeekOpen(false)
    } else if (peekOpen && highlightedId === null) {
      setPeekOpen(false)
    }
    previousOrder.current = rows.map((row) => row.id)
  })
  useEffect(() => reconcile(), [rows, highlightedId, peekOpen, ready])

  useEffect(() => {
    if (!showPeek) return
    const list = listRef
    // the panel's focused control is removed with it, which would drop focus to the body
    return () => {
      if (document.activeElement === document.body) list.current?.focus({ preventScroll: true })
    }
  }, [showPeek])

  useEffect(() => {
    if (autoFocus) listRef.current?.focus({ preventScroll: true })
  }, [autoFocus])

  useEffect(() => {
    if (highlightedId === null) return
    const element = document.getElementById(`${uid}-row-${encodeURIComponent(highlightedId)}`)
    element?.scrollIntoView({ block: "nearest" })
  }, [highlightedId, uid])

  const onFilterKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Escape") {
      event.preventDefault()
      if (filter) setFilter("")
      else {
        event.currentTarget.blur()
        focusList()
      }
    } else if (event.key === "ArrowDown") {
      event.preventDefault()
      if (rows.length > 0) {
        setHighlightedId(rows[0].id)
        focusList()
      }
    }
  }

  const count = filter.trim()
    ? `${rows.length} of ${items.length} items`
    : `${items.length} ${items.length === 1 ? "item" : "items"}`

  let listArea: ReactNode
  if (status === "loading") {
    listArea = <LoadingState label="Loading items" />
  } else if (status === "error") {
    listArea = <ErrorState error={error ?? new Error("Unknown error")} onRetry={onRetry} />
  } else if (items.length === 0) {
    listArea = (
      <EmptyState
        title={emptyTitle}
        description="Items you add will show up here."
        action={
          emptyAction ? (
            <Button variant="outline" size="sm" onClick={emptyAction.onClick}>
              {emptyAction.label}
            </Button>
          ) : undefined
        }
      />
    )
  } else if (rows.length === 0) {
    listArea = (
      <EmptyState
        title={`No items match "${filter.trim()}"`}
        description="Try a different word, or clear the filter."
        action={
          <Button variant="outline" size="sm" onClick={() => setFilter("")}>
            Clear filter
          </Button>
        }
      />
    )
  } else {
    const renderRow = (item: T) => {
      const highlighted = item.id === highlightedId
      return (
        <div
          key={item.id}
          id={rowDomId(item.id)}
          role="option"
          data-mini="row"
          aria-selected={highlighted}
          title={item.title}
          onClick={(event) => onRowClick(event, item)}
          onDoubleClick={(event) => onRowDoubleClick(event, item)}
          onMouseEnter={() => {
            hoveredId.current = item.id
          }}
          onMouseLeave={() => {
            if (hoveredId.current === item.id) hoveredId.current = null
          }}
          className={cn(
            "flex h-10 cursor-default select-none items-center gap-3 border-b border-border/60 px-3",
            highlighted ? "bg-accent" : "hover:bg-accent/50"
          )}
        >
          {renderLead ? (
            <span className="w-16 shrink-0 truncate text-xs text-muted-foreground tabular-nums">
              {renderLead(item)}
            </span>
          ) : null}
          <span className="min-w-0 flex-1 truncate">{item.title}</span>
          {renderMeta ? (
            <span className="min-w-12 max-w-[40%] shrink-[100] truncate text-xs text-muted-foreground">
              {renderMeta(item)}
            </span>
          ) : null}
        </div>
      )
    }

    listArea = (
      <div
        ref={listRef}
        role="listbox"
        tabIndex={0}
        aria-label={ariaLabel}
        aria-activedescendant={active ? rowDomId(active.id) : undefined}
        className="h-full overflow-y-auto outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50"
      >
        {sections.map((section, index) =>
          section.name === null ? (
            section.rows.map(renderRow)
          ) : (
            <div key={section.name} role="group" aria-labelledby={`${uid}-group-${index}`}>
              <div
                id={`${uid}-group-${index}`}
                data-mini="group-header"
                className="flex h-9 items-center gap-2 border-b border-border/60 bg-muted/60 px-3 text-xs font-medium"
              >
                <span className="truncate">{section.name}</span>
                <span className="text-muted-foreground tabular-nums">{section.rows.length}</span>
              </div>
              {section.rows.map(renderRow)}
            </div>
          )
        )}
      </div>
    )
  }

  const step = (delta: 1 | -1) => {
    const target = rows[activeIndex + delta]
    if (target) setHighlightedId(target.id)
  }

  return (
    <div ref={rootRef} className="@container flex h-full min-h-0 flex-col bg-background text-sm">
      <div className="flex h-11 shrink-0 items-center gap-3 border-b px-3">
        <Input
          ref={inputRef}
          value={filter}
          onChange={(event) => setFilter(event.target.value)}
          onKeyDown={onFilterKeyDown}
          disabled={!ready}
          placeholder="Filter (press /)"
          aria-label="Filter items"
          className="h-8 max-w-64"
        />
        <span
          aria-live="polite"
          className="ml-auto shrink-0 text-xs text-muted-foreground tabular-nums"
        >
          {ready ? count : ""}
        </span>
      </div>
      <div className="relative flex min-h-0 flex-1">
        <div className="min-h-0 min-w-0 flex-1">{listArea}</div>
        {showPeek ? (
          <aside
            ref={panelRef}
            aria-label="Preview"
            data-mini="panel"
            className="flex min-h-0 w-[42%] shrink-0 flex-col border-l bg-background @max-[720px]:absolute @max-[720px]:inset-0 @max-[720px]:z-10 @max-[720px]:w-full @max-[720px]:border-l-0"
          >
            <div className="flex h-11 shrink-0 items-center gap-1 border-b px-3">
              <span
                aria-live="polite"
                className="mr-auto text-xs text-muted-foreground tabular-nums"
              >
                {activeIndex + 1} / {rows.length}
              </span>
              <Button
                variant="ghost"
                size="icon-xs"
                aria-label="Previous item"
                aria-disabled={activeIndex === 0}
                className="aria-disabled:opacity-40"
                onClick={() => step(-1)}
              >
                <ChevronUpIcon aria-hidden />
              </Button>
              <Button
                variant="ghost"
                size="icon-xs"
                aria-label="Next item"
                aria-disabled={activeIndex === rows.length - 1}
                className="aria-disabled:opacity-40"
                onClick={() => step(1)}
              >
                <ChevronDownIcon aria-hidden />
              </Button>
              <Button variant="ghost" size="icon-xs" aria-label="Close preview" onClick={closePeek}>
                <XIcon aria-hidden />
              </Button>
            </div>
            <ScrollArea className="min-h-0 flex-1 [&_[data-slot=scroll-area-viewport]>div]:block!">
              <div className="p-4 break-words">{renderPeek(active)}</div>
            </ScrollArea>
          </aside>
        ) : null}
      </div>
    </div>
  )
}
